import React, { useState } from 'react'
import { Form, Button} from "react-bootstrap";
import {Link} from 'react-router-dom'
import{useForm} from 'react-hook-form'


const LoginPage =()=>{

    const {register, handleSubmit,watch,formState:{errors}}=useForm()

   

    const loginUser=()=>{
